70	
71	    /** Dedicated audit logger; each successful owner create emits one line here. */
72	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
73	
74	    /**
75	     * Monotonically increasing sequence stamped onto each structured {@code OWNER_CREATED}
76	     * event, shared across every controller instance so the {@code seq} strictly increases
77	     * across all owner creates for the life of the process.
78	     */
79	    private static final java.util.concurrent.atomic.AtomicLong AUDIT_EVENT_SEQ =
80	        new java.util.concurrent.atomic.AtomicLong();
81	
82	    /**
83	     * The header carrying an idempotency key for owner creation. When a create repeats with a key
84	     * already seen, the originally created owner is returned with 200 instead of creating a duplicate.
85	     */
86	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
87	
88	    /**
89	     * Remembers, per seen idempotency key, the id of the owner that create originally produced, so a
90	     * repeat of the same request returns that owner rather than creating a duplicate.
91	     */
92	    private final Map<String, Integer> idempotentCreates = new java.util.concurrent.ConcurrentHashMap<>();
93	
