323	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
324	    @Override
325	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
326	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
327	        if (currentOwner == null) {
328	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
329	        }
330	        currentOwner.setAddress(ownerFieldsDto.getAddress());
331	        currentOwner.setCity(ownerFieldsDto.getCity());
332	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
333	        currentOwner.setLastName(ownerFieldsDto.getLastName());
334	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
335	        this.clinicService.saveOwner(currentOwner);
336	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
337	    }
