339	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
340	    @Transactional
341	    @Override
342	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
343	        Owner owner = this.clinicService.findOwnerById(ownerId);
344	        if (owner == null) {
345	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
346	        }
347	        // Soft delete: the row is retained and flagged deleted rather than removed, so the
348	        // owner is still readable via GET but is ignored by the create duplicate/identity checks.
349	        owner.setDeleted(true);
350	        this.clinicService.saveOwner(owner);
351	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
352	    }
