419	    /**
420	     * The maximum number of owners permitted per city. Owner creation is rejected once the
421	     * owner's city already contains this many owners.
422	     */
423	    private static final int MAX_OWNERS_PER_CITY = 50;
424	
425	    /**
426	     * Counts how many existing owners live in the given city, compared case-insensitively.
427	     * This is evaluated before the new owner is persisted, so the owner being created is not
428	     * included in the count.
429	     *
430	     * @param city the new owner's city
431	     * @return the number of existing owners in that city
432	     */
433	    private int countOwnersInCity(String city) {
434	        int count = 0;
435	        for (Owner existing : this.clinicService.findAllOwners()) {
436	            if (city.equalsIgnoreCase(existing.getCity())) {
437	                count++;
438	            }
439	        }
440	        return count;
441	    }
442	
443	    /**
444	     * The number of owners in a city at or above which a capacity warning is raised. Once the
445	     * owner's city holds at least this many owners (but is still below {@link #MAX_OWNERS_PER_CITY},
446	     * the hard limit), the city is approaching capacity and {@code capacityWarning} is reported as
447	     * {@code true} in the owner response.
448	     */
449	    private static final int CAPACITY_WARNING_THRESHOLD = 40;
450	
451	    /**
452	     * Reports whether the given city is approaching the per-city capacity limit, i.e. whether it
453	     * already holds between {@link #CAPACITY_WARNING_THRESHOLD} (40) and
454	     * {@link #MAX_OWNERS_PER_CITY} minus one (49) owners inclusive. At the hard limit of 50 the
455	     * create is rejected outright, so a full city never warns.
456	     *
457	     * @param city the owner's city
458	     * @return {@code true} when the city holds 40-49 owners, otherwise {@code false}
459	     */
460	    private boolean isApproachingCapacity(String city) {
461	        int count = countOwnersInCity(city);
462	        return count >= CAPACITY_WARNING_THRESHOLD && count < MAX_OWNERS_PER_CITY;
463	    }
464	
465	    /**
466	     * The maximum number of owners that may be created in a single business day. Owner
467	     * creation is rejected once this many owners already fall on the new owner's adjusted
468	     * business day {@code registrationDate}.
469	     */
470	    private static final int MAX_OWNERS_PER_DAY = 100;
471	
472	    /**
473	     * The fixed list of public holidays that the business-day roll skips over. A date that
474	     * lands on one of these is rolled forward to the next non-holiday business day.
475	     */
476	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
477	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
478	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
479	        LocalDate.parse("2026-12-28"));
480	
481	    /**
482	     * Rolls a date forward to the next business day: a Saturday, Sunday or listed public
483	     * holiday is moved forward one day at a time until a non-holiday weekday is reached,
484	     * while a date that is already a non-holiday weekday is returned unchanged.
485	     *
486	     * @param date the date to adjust
487	     * @return the same date if it is a non-holiday weekday, otherwise the next such day
488	     */
489	    private LocalDate toBusinessDay(LocalDate date) {
490	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
491	                || PUBLIC_HOLIDAYS.contains(date)) {
492	            date = date.plusDays(1);
493	        }
494	        return date;
495	    }
496	
497	    /**
498	     * Counts how many existing owners fall on the given business day, i.e. whose {@code
499	     * registrationDate} rolls forward to the same business day. This is evaluated before the
500	     * new owner is persisted, so the owner being created is not included in the count.
501	     *
502	     * @param businessDay the adjusted business day to count against
503	     * @return the number of existing owners registered on that business day
504	     */
505	    private int countOwnersRegisteredOn(LocalDate businessDay) {
506	        int count = 0;
507	        for (Owner existing : this.clinicService.findAllOwners()) {
508	            LocalDate existingDate = existing.getRegistrationDate();
509	            if (existingDate != null && businessDay.equals(toBusinessDay(existingDate))) {
510	                count++;
511	            }
512	        }
513	        return count;
514	    }
515	
516	    /**
517	     * The number of owners that may be created on a single business day before a bulk-signup
518	     * warning is raised. Once more than this many owners already fall on the current business
519	     * day, {@code bulkSignupWarning} is reported as {@code true} in the owner response.
520	     */
521	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
522	
523	    /**
524	     * Reports whether an unusually high number of owners have been created for today's business
525	     * day, i.e. whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already fall on
526	     * the business day that {@code LocalDate.now()} rolls forward to.
527	     *
528	     * @return {@code true} once more than 80 owners have been created today, otherwise {@code false}
529	     */
530	    private boolean isBulkSignupDay() {
531	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > BULK_SIGNUP_WARNING_THRESHOLD;
532	    }
533	
534	    /**
535	     * Builds the unified member id for a newly created owner, formatted
536	     * {@code '<REGION><FY><HASH8><CHK>'} where {@code REGION} is the canonical region
537	     * {@link OwnerLocality#forPostcodeOrUnknown derived from the postcode} (or
538	     * {@code "UNKNOWN"} when the postcode resolves no region), {@code FY} is the last two
539	     * digits of the fiscal year of the business-day-adjusted registration date (fiscal year
540	     * starts 1 July, named by the year it ends in), {@code HASH8} is the first eight
541	     * upper-case hex characters of the SHA-256 digest of {@code normalizedTelephone + lastName}
542	     * (the same hash used by the region-and-hash identity), and {@code CHK} is a single Luhn
543	     * check digit computed over the digits of {@code '<REGION><FY><HASH8>'}. The id carries no
544	     * sequence number, so it is stable for a given telephone, last name and fiscal year rather
545	     * than dependent on creation order.
546	     *
547	     * @param postcode            the owner's postcode (may be {@code null})
548	     * @param normalizedTelephone the owner's normalized E.164 telephone
549	     * @param lastName            the owner's last name
550	     * @param registrationDate    the owner's business-day-adjusted registration date
551	     * @return the assigned member id (e.g. {@code 'NSW271A2B3C4D5'})
552	     */
553	    private static String memberId(String postcode, String normalizedTelephone, String lastName,
554	        LocalDate registrationDate) {
555	        String region = org.springframework.samples.petclinic.mapper.OwnerLocality.forPostcodeOrUnknown(postcode);
556	        int fiscalYear = org.springframework.samples.petclinic.mapper.FiscalYear.yearValue(registrationDate);
557	        String fy = String.format("%02d", Math.floorMod(fiscalYear, 100));
558	        String base = region + fy + sha256Hex8(normalizedTelephone + lastName);
559	        int chk = org.springframework.samples.petclinic.mapper.OwnerLocality.luhn(base);
560	        return base + chk;
561	    }
562	
563	    /**
564	     * De-duplicates a freshly computed {@code base} member id against the ids already
565	     * assigned to existing owners. When {@code base} is free it is returned unchanged;
566	     * otherwise {@code '-<n>'} is appended with the smallest {@code n} of two or more that
567	     * yields an id no existing owner holds.
568	     *
569	     * @param base the computed {@code '<REGION><FY><HASH8><CHK>'} member id
570	     * @return {@code base}, or {@code base + "-<n>"} de-duplicated to be unique
571	     */
572	    private String deduplicatedMemberId(String base) {
573	        Set<String> existing = new HashSet<>();
574	        for (Owner owner : this.clinicService.findAllOwners()) {
575	            if (owner.getMemberId() != null) {
576	                existing.add(owner.getMemberId());
577	            }
578	        }
579	        if (!existing.contains(base)) {
580	            return base;
581	        }
582	        int n = 2;
583	        while (existing.contains(base + "-" + n)) {
584	            n++;
585	        }
586	        return base + "-" + n;
587	    }
588	
589	    /**
590	     * Returns the first eight upper-case hex characters of the SHA-256 digest of the UTF-8
591	     * bytes of {@code source} — the {@code HASH8} component of an owner's member id.
592	     *
593	     * @param source the string to hash
594	     * @return the first eight upper-case hex characters of {@code SHA-256(source)}
595	     */
596	    private static String sha256Hex8(String source) {
597	        try {
598	            byte[] digest = MessageDigest.getInstance("SHA-256")
599	                .digest(source.getBytes(StandardCharsets.UTF_8));
600	            StringBuilder hex = new StringBuilder(digest.length * 2);
601	            for (byte b : digest) {
602	                hex.append(String.format("%02x", b));
603	            }
604	            return hex.substring(0, 8).toUpperCase();
605	        } catch (NoSuchAlgorithmException e) {
606	            throw new IllegalStateException("SHA-256 not available", e);
607	        }
608	    }
609	
610	    /**
611	     * Counts how many existing owners share the given first and last name, compared
612	     * case-insensitively. This is evaluated before the new owner is persisted, so the
613	     * owner being created is not included in the count.
614	     *
615	     * @param firstName the new owner's first name
616	     * @param lastName  the new owner's last name
617	     * @return the number of existing owners with the same first and last name
618	     */
619	    private int countNamesakes(String firstName, String lastName) {
620	        int count = 0;
621	        for (Owner existing : this.clinicService.findAllOwners()) {
622	            if (firstName.equalsIgnoreCase(existing.getFirstName())
623	                && lastName.equalsIgnoreCase(existing.getLastName())) {
624	                count++;
625	            }
626	        }
627	        return count;
628	    }
629	
630	    /**
631	     * Canonical expansions applied to common street-type abbreviations during address
632	     * normalization. Keys and values are upper-cased so the lookup runs after the address
633	     * has itself been upper-cased.
634	     */
635	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
636	        "ST", "STREET",
637	        "RD", "ROAD",
638	        "AVE", "AVENUE");
639	
640	    /**
641	     * Normalizes an owner address for creation. Leading and trailing whitespace is trimmed,
642	     * every run of internal whitespace is collapsed to a single space, the result is
643	     * upper-cased and common street-type abbreviations are expanded ({@code ST -> STREET},
644	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). An abbreviation is recognized as a whole
645	     * token, optionally carrying a single trailing full stop (so both {@code 'St'} and
646	     * {@code 'St.'} become {@code 'STREET'}). The normalized value is what gets stored,
647	     * returned and compared for household duplicates; an address that is blank once
648	     * normalized fails the required-field check.
649	     *
650	     * @param address the raw address value supplied by the client
651	     * @return the normalized address (empty string when {@code address} is null or blank)
652	     */
653	    /**
654	     * Normalizes the address an owner supplies, preferring the structured form, and stores the
655	     * normalized structured lines on the owner. When a non-blank {@code addressLine1} is present
656	     * the structured fields are used: {@code addressLine1} (and {@code addressLine2}, when
657	     * present) are {@link #normalizeAddress normalized} and set on the owner, and the composed
658	     * address returned is the normalized {@code addressLine1} with a single space and the
659	     * normalized {@code addressLine2} appended when {@code addressLine2} is present. Otherwise
660	     * the flat {@code address} is normalized and returned, and the structured lines are left
661	     * unset. The returned value becomes the owner's stored {@code address}, read by everything
662	     * downstream (household hash, postcode validation and locality); an owner that supplies
663	     * neither form yields an empty string, failing the required-address check.
664	     *
665	     * @param owner          the owner being created, whose structured address lines are set here
666	     * @param ownerFieldsDto the submitted owner fields
667	     * @return the composed, normalized address (empty string when no address form is supplied)
668	     */
669	    private static String applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
670	        String addressLine1 = ownerFieldsDto.getAddressLine1();
671	        if (addressLine1 != null && !addressLine1.isBlank()) {
672	            String normalizedLine1 = normalizeAddress(addressLine1);
673	            owner.setAddressLine1(normalizedLine1);
674	            String addressLine2 = ownerFieldsDto.getAddressLine2();
675	            if (addressLine2 != null && !addressLine2.isBlank()) {
676	                String normalizedLine2 = normalizeAddress(addressLine2);
677	                owner.setAddressLine2(normalizedLine2);
678	                return normalizedLine1 + " " + normalizedLine2;
679	            }
680	            owner.setAddressLine2(null);
681	            return normalizedLine1;
682	        }
683	        owner.setAddressLine1(null);
684	        owner.setAddressLine2(null);
685	        return normalizeAddress(ownerFieldsDto.getAddress());
686	    }
687	
688	    private static String normalizeAddress(String address) {
689	        if (address == null) {
690	            return "";
691	        }
692	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
693	        if (collapsed.isEmpty()) {
694	            return "";
695	        }
696	        StringBuilder normalized = new StringBuilder(collapsed.length());
697	        for (String token : collapsed.split(" ")) {
698	            String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
699	            String expanded = ADDRESS_ABBREVIATIONS.get(core);
700	            if (normalized.length() > 0) {
701	                normalized.append(' ');
702	            }
703	            normalized.append(expanded != null ? expanded : token);
704	        }
705	        return normalized.toString();
706	    }
707	
708	    /**
709	     * Normalizes a last name or address for household-duplicate comparison: leading and
710	     * trailing whitespace is trimmed, every run of internal whitespace is collapsed to a
711	     * single space and the result is lower-cased. Two owners are considered to share a
712	     * household when both their last names and addresses produce the same key.
713	     *
714	     * @param value the raw last name or address value
715	     * @return the normalized comparison key (empty string when {@code value} is null)
716	     */
717	    private static String householdKey(String value) {
718	        if (value == null) {
719	            return "";
720	        }
721	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
722	    }
723	
724	    /**
725	     * Derives the stable shared household identifier for the given normalized last name key
726	     * and postcode. The identifier is deterministic — the same household (same
727	     * {@link #householdKey normalized} last name and postcode) always maps to the same
728	     * value — so every owner in a household is assigned an identical id. It is the
729	     * upper-cased first twelve hex characters of the SHA-256 digest of {@code
730	     * '<lastNameKey>|<postcode>'}.
731	     *
732	     * @param lastNameKey the normalized last name key
733	     * @param postcode    the owner's postcode
734	     * @return the shared household identifier
735	     */
736	    private static String householdId(String lastNameKey, String postcode) {
737	        String source = lastNameKey + "|" + postcode;
738	        try {
739	            byte[] digest = MessageDigest.getInstance("SHA-256")
740	                .digest(source.getBytes(StandardCharsets.UTF_8));
741	            StringBuilder hex = new StringBuilder(digest.length * 2);
742	            for (byte b : digest) {
743	                hex.append(String.format("%02x", b));
744	            }
745	            return hex.substring(0, 12).toUpperCase();
746	        } catch (NoSuchAlgorithmException e) {
747	            throw new IllegalStateException("SHA-256 not available", e);
748	        }
749	    }
750	
751	    /**
752	     * Computes the deterministic {@link #householdId household id} an existing owner belongs to,
753	     * derived from its {@link #householdKey normalized} last name and its postcode. Returns
754	     * {@code null} when the owner has no postcode (such an owner has no household), so it never
755	     * collides with a computed household id.
756	     *
757	     * @param owner the existing owner
758	     * @return the owner's household id, or {@code null} when it has no postcode
759	     */
760	    private static String computeHouseholdId(Owner owner) {
761	        if (owner.getPostcode() == null) {
762	            return null;
763	        }
764	        return householdId(householdKey(owner.getLastName()), owner.getPostcode());
765	    }
766	
767	    /**
768	     * Populates an owner's {@code membershipPoints} and {@code membershipLevel} on the given
769	     * dto, sizing the owner's household from all owners so the household-of-three-or-more
770	     * factor is scored correctly. Use {@link #applyMembership(OwnerDto, Owner, Map)} instead
771	     * when mapping a collection to size every household from a single scan.
772	     *
773	     * @param ownerDto the dto to populate
774	     * @param owner    the owner being mapped
775	     */
776	    private void applyMembership(OwnerDto ownerDto, Owner owner) {
777	        applyMembership(ownerDto, owner, householdSizes());
778	    }
779	
780	    /**
781	     * Populates an owner's {@code membershipPoints} and {@code membershipLevel} on the given
782	     * dto using a pre-computed map of household id to member count.
783	     *
784	     * @param ownerDto       the dto to populate
785	     * @param owner          the owner being mapped
786	     * @param householdSizes household id to member count, as returned by {@link #householdSizes()}
787	     */
788	    private void applyMembership(OwnerDto ownerDto, Owner owner, Map<String, Integer> householdSizes) {
789	        int householdSize = owner.getHouseholdId() == null ? 1
790	            : householdSizes.getOrDefault(owner.getHouseholdId(), 1);
791	        int points = MembershipPoints.points(owner, householdSize);
792	        ownerDto.setMembershipPoints(points);
793	        ownerDto.setMembershipLevel(MembershipPoints.level(points));
794	        applyOwnerSegment(ownerDto);
795	    }
796	
797	    /**
798	     * Populates an owner's {@code ownerSegment} on the given dto from its already-applied
799	     * {@code membershipLevel} and mapped {@code locality}. Call this whenever the membership
800	     * level changes (e.g. after {@link #capMembershipLevelToHousehold}) so the segment stays
801	     * consistent with the level.
802	     *
803	     * @param ownerDto the dto whose membershipLevel and locality are already populated
804	     */
805	    private void applyOwnerSegment(OwnerDto ownerDto) {
806	        Integer membershipLevel = ownerDto.getMembershipLevel();
807	        int level = membershipLevel == null ? 1 : membershipLevel;
808	        ownerDto.setOwnerSegment(org.springframework.samples.petclinic.mapper.OwnerSegment.segment(
809	            level, ownerDto.getLocality()));
810	    }
811	
812	    /**
813	     * Caps a newly created owner's {@code membershipLevel} at one above the highest
814	     * {@code membershipLevel} among the other current members of its household, writing the
815	     * capped value back onto the dto and returning it. A member's current level is scored the
816	     * same way as {@link #applyMembership}, using {@code householdSizes} so the
817	     * household-of-three-or-more factor reflects the household as it now stands. When the owner
818	     * has no household, or is the only member of its household, no cap applies and the level is
819	     * returned unchanged.
820	     *
821	     * @param ownerDto       the newly created owner's dto, with its uncapped membership already applied
822	     * @param owner          the newly created owner (already saved, so it has an id)
823	     * @param householdSizes household id to member count, as returned by {@link #householdSizes()}
824	     * @return the resulting (possibly capped) membership level
825	     */
826	    private int capMembershipLevelToHousehold(OwnerDto ownerDto, Owner owner,
827	        Map<String, Integer> householdSizes) {
828	        int level = ownerDto.getMembershipLevel();
829	        String householdId = owner.getHouseholdId();
830	        if (householdId == null) {
831	            return level;
832	        }
833	        Integer maxMemberLevel = null;
834	        for (Owner existing : this.clinicService.findAllOwners()) {
835	            if (existing.isDeleted() || existing.getId().equals(owner.getId())) {
836	                continue;
837	            }
838	            if (householdId.equals(existing.getHouseholdId())) {
839	                int size = householdSizes.getOrDefault(householdId, 1);
840	                int memberLevel = MembershipPoints.level(MembershipPoints.points(existing, size));
841	                maxMemberLevel = maxMemberLevel == null ? memberLevel
842	                    : Math.max(maxMemberLevel, memberLevel);
843	            }
844	        }
845	        if (maxMemberLevel != null && level > maxMemberLevel + 1) {
846	            level = maxMemberLevel + 1;
847	            ownerDto.setMembershipLevel(level);
848	        }
849	        return level;
850	    }
851	
852	    /**
853	     * Counts how many owners belong to each household, keyed by household id. Owners without a
854	     * household id (no postcode) are excluded — such an owner is its own single-member household.
855	     *
856	     * @return a map from household id to the number of owners sharing it
857	     */
858	    private Map<String, Integer> householdSizes() {
859	        Map<String, Integer> sizes = new java.util.HashMap<>();
860	        for (Owner existing : this.clinicService.findAllOwners()) {
861	            String householdId = existing.getHouseholdId();
862	            if (householdId != null) {
863	                sizes.merge(householdId, 1, Integer::sum);
864	            }
865	        }
866	        return sizes;
867	    }
868	
869	    /**
870	     * Applies soft-match (possible-duplicate) detection to a new owner that has already
871	     * cleared hard {@code identityKey} duplicate rejection. The owner is flagged as a
872	     * possible duplicate when a non-deleted existing owner shares its {@link
873	     * OwnerIdentity#soundex soundex(lastName)} and its postcode while producing a different
874	     * {@code identityKey}; {@code possibleDuplicateOf} is then set to that existing owner's id.
875	     * Because the telephone is part of the identity key, two owners with the same last name and
876	     * postcode but different telephones differ in their keys and so surface here as a soft match
877	     * rather than a hard duplicate. When several existing owners match, the one with the lowest
878	     * id is chosen so the result is deterministic. When no such owner exists — or the new owner
879	     * has no postcode to compare — {@code possibleDuplicate} is set to {@code false} and no
880	     * matching id is recorded.
881	     *
882	     * @param owner the new owner, already normalized (E.164 telephone, validated postcode)
883	     */
884	    private void applyPossibleDuplicate(Owner owner) {
885	        owner.setPossibleDuplicate(false);
886	        if (owner.getPostcode() == null) {
887	            return;
888	        }
889	        String soundex = OwnerIdentity.soundex(owner.getLastName());
890	        String identityKey = OwnerIdentity.identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
891	        Owner match = null;
892	        for (Owner existing : this.clinicService.findAllOwners()) {
893	            if (existing.isDeleted()) {
894	                continue;
895	            }
896	            if (soundex.equals(OwnerIdentity.soundex(existing.getLastName()))
897	                && owner.getPostcode().equals(existing.getPostcode())
898	                && !identityKey.equals(OwnerIdentity.identityKey(toE164(existing.getTelephone()),
899	                    existing.getEmail(), existing.getLastName()))) {
900	                if (match == null || (existing.getId() != null
901	                    && existing.getId() < match.getId())) {
902	                    match = existing;
903	                }
904	            }
905	        }
906	        if (match != null) {
907	            owner.setPossibleDuplicate(true);
908	            owner.setPossibleDuplicateOf(match.getId());
909	        }
910	    }
911	
912	    /**
913	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes
914	     * and brackets are stripped. When the number already carries a leading {@code '+'}
915	     * and country code these are kept; a number written in national trunk form (a leading
916	     * {@code '0'}) is treated as Australian, so the {@code '0'} is dropped and country code
917	     * {@code '+61'} prepended; any other bare number is treated as a NANP number and country
918	     * code {@code '+1'} is prepended. The resulting number must have between 8 and 15 digits
919	     * after the {@code '+'}, and its national-number length must be valid for the detected
920	     * country code (see {@link #hasValidNationalLength}).
921	     *
922	     * @param telephone the raw telephone value supplied by the client
923	     * @return the E.164 telephone (e.g. {@code +61412345678}), or {@code null} when it
924	     *         cannot form a valid E.164 number (signalling a 400 Bad Request)
925	     */
926	    private static String toE164(String telephone) {
927	        if (telephone == null) {
928	            return null;
929	        }
930	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
931	        String digits;
932	        if (cleaned.startsWith("+")) {
933	            digits = cleaned.substring(1);
934	        } else if (cleaned.startsWith("0")) {
935	            digits = "61" + cleaned.substring(1);
936	        } else {
937	            digits = "1" + cleaned;
938	        }
939	        if (!digits.matches("[0-9]{8,15}")) {
940	            return null;
941	        }
942	        if (!hasValidNationalLength(digits)) {
943	            return null;
944	        }
945	        return "+" + digits;
946	    }
947	
948	    /**
949	     * Validates the national-number length of an E.164 digit string against its country
950	     * code: Australia ({@code +61}) requires exactly 9 national digits and the NANP
951	     * ({@code +1}) requires exactly 10. Numbers under any other country code are not
952	     * length-checked here — only the general 8-to-15-digit E.164 bound applies to them.
953	     *
954	     * @param digits the E.164 digits (without the leading {@code '+'})
955	     * @return {@code true} when the national-number length is valid for the country code
956	     */
957	    private static boolean hasValidNationalLength(String digits) {
958	        if (digits.startsWith("61")) {
959	            return digits.length() - 2 == 9;
960	        }
961	        if (digits.startsWith("1")) {
962	            return digits.length() - 1 == 10;
963	        }
964	        return true;
965	    }
966	
967	    /**
968	     * Inclusive 4-digit postcode ranges permitted for each canonical region: NSW 2000-2099,
969	     * VIC 3000-3099 and QLD 4000-4099. A region absent from this table (e.g. the {@code
970	     * "UNKNOWN"} derived for a city with no known region) imposes no range restriction.
971	     */
972	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
973	        "NSW", new int[] {2000, 2099},
974	        "VIC", new int[] {3000, 3099},
975	        "QLD", new int[] {4000, 4099});
976	
977	    /**
978	     * Validates an owner's postcode for creation. A postcode is only ever validated when
979	     * present (an absent postcode is optional and accepted). When present it must be exactly
980	     * four digits and, for a city whose {@link OwnerLocality#forCity region} has a known
981	     * postcode range, must fall inside that inclusive range (NSW 2000-2099, VIC 3000-3099,
982	     * QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
983	     *
984	     * @param postcode the supplied postcode (never {@code null} here)
985	     * @param city     the owner's city, used to derive the region
986	     * @return {@code true} when the postcode is valid for the city, {@code false} otherwise
987	     *         (signalling a 400 Bad Request)
988	     */
989	    private static boolean isValidPostcode(String postcode, String city) {
990	        if (!postcode.matches("[0-9]{4}")) {
991	            return false;
992	        }
993	        int[] range = REGION_POSTCODES.get(
994	            org.springframework.samples.petclinic.mapper.OwnerLocality.forCity(city));
995	        if (range == null) {
996	            return true;
997	        }
998	        int value = Integer.parseInt(postcode);
999	        return value >= range[0] && value <= range[1];
1000	    }
1001	
1002	    /**
1003	     * Disposable email domains that are not accepted for owner creation. An owner whose
1004	     * email domain (compared case-insensitively) is in this set is rejected with a 400
1005	     * Bad Request.
1006	     */
1007	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
1008	        "mailinator.com", "tempmail.com", "guerrillamail.com");
1009	
1010	    /**
1011	     * Normalizes an owner email for creation. A present email must be a syntactically
1012	     * valid address whose domain is not on the disposable-domain blocklist ({@link
1013	     * #DISPOSABLE_EMAIL_DOMAINS}); the returned value is lower-cased.
1014	     *
1015	     * @param email the raw email value supplied by the client (never {@code null} here)
1016	     * @return the lower-cased email, or {@code null} when it is not a syntactically valid
1017	     *         address or its domain is a disposable domain (signalling a 400 Bad Request)
1018	     */
1019	    private static String normalizeEmail(String email) {
1020	        String trimmed = email.trim();
1021	        if (!trimmed.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")) {
1022	            return null;
1023	        }
1024	        String normalized = trimmed.toLowerCase();
1025	        String domain = normalized.substring(normalized.indexOf('@') + 1);
1026	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
1027	            return null;
1028	        }
1029	        return normalized;
1030	    }
1031	}
